VALUES (37724, 'tt1074638', NULL, 'Skyfall', 'Skyfall', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/d0IVecFQvsGdSbnMAHqiYsNYaJT.jpg', 'https://image.tmdb.org/t/p/original/wkA622CCN2X0uwpgqYEOnUYEDf5.jpg', 'When Bond''s latest assignment goes gravely wrong, agents around the world are exposed and MI6 headquarters is attacked. While M faces challenges to her authority and position from Gareth Mallory, the new Chairman of the Intelligence and Security Committee, it''s up to Bond, aided only by field agent Eve, to locate the mastermind behind the attack.', NULL, NULL, 15.8274, 7.269, 0, 2.48019047619047618e+01, '2026-07-15 12:01:52', '2026-11-19 13:22:38')
