VALUES (612, 'tt0408306', NULL, 'Munich', 'Munich', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/iUekaw96QLInZpsNwRTlRKrZgwm.jpg', 'https://image.tmdb.org/t/p/original/titl6uMe5u974sLAA2Zy1kFi4sC.jpg', 'During the 1972 Olympic Games in Munich, eleven Israeli athletes are taken hostage and murdered by a Palestinian terrorist group known as Black September. In retaliation, the Israeli government recruits a group of Mossad agents to track down and execute those responsible for the attack.', NULL, NULL, 5.3453, 7.13, 0, 1.1913636363636364e+01, '2026-07-20 01:02:04', '2026-11-19 13:22:38')
