VALUES (11657, 'tt0065531', NULL, 'Le Cercle Rouge', 'Le Cercle rouge', 'movie', 1970, 'https://image.tmdb.org/t/p/w500/w56La43IJnGpLepgqfGCAZsbQPp.jpg', 'https://image.tmdb.org/t/p/original/93iDrZmjDF01Tn3PxOYL8Zz9hBM.jpg', 'When French criminal Corey gets released from prison, he resolves to never return. He is quickly pulled back into the underworld, however, after a chance encounter with escaped murderer Vogel. Along with former policeman and current alcoholic Jansen, they plot an intricate jewel heist. All the while, quirky Police Commissioner Mattei, who was the one to lose custody of Vogel, is determined to find him.', NULL, NULL, 2.2381, 7.6, 0, 6.842, '2026-07-20 01:02:04', '2026-11-19 13:22:38')
