VALUES (303, 'tt0038787', NULL, 'Notorious', 'Notorious', 'movie', 1946, 'https://image.tmdb.org/t/p/w500/e7DHQGgivZyMvM4z7mA7gMNvOHg.jpg', 'https://image.tmdb.org/t/p/original/6jRd6vT3NhwIeyqaiWCYzi64lSP.jpg', 'In order to help bring Nazis to justice, U.S. government agent T.R. Devlin recruits Alicia Huberman, the American daughter of a convicted German war criminal, as a spy. As they begin to fall for one another, Alicia is instructed to win the affections of Alexander Sebastian, a Nazi hiding out in Brazil. When Sebastian becomes serious about his relationship with Alicia, the stakes get higher, and Devlin must watch her slip further undercover.', NULL, NULL, 3.4564, 7.7, 0, 10.9225, '2026-07-21 03:32:24', '2026-11-19 13:22:38')
