VALUES (44026, 'tt0048393', NULL, 'Mr. Arkadin', 'Mr. Arkadin', 'movie', 1955, 'https://image.tmdb.org/t/p/w500/hoBfh3jmA3XDDx9tGgMwdGd37GE.jpg', 'https://image.tmdb.org/t/p/original/dSBvYxsJnfIVqpkVu1xDSVSsMvv.jpg', 'Claiming that he doesn''t know his own past, a rich man enlists an ex-con with an odd bit of detective work. Gregory Arkadin says he can''t remember anything before the late 1920s, and convict Guy Van Stratten is happy to take the job of exploring his new acquaintance''s life story. Guy''s research turns up stunning details about his employer''s past, and as his work seems linked to untimely deaths, the mystery surrounding Mr. Arkadin deepens.', NULL, NULL, 1.2438, 6.841, 0, 6.09, '2026-07-21 03:32:24', '2026-11-19 13:22:38')
